def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    if n <= 3:
        for h in history:
            if h[1] == 'D':
                return 'D'
        return 'C'
    if len(history) >= 2 and history[-1][1] == 'D' and history[-2][1] == 'D':
        return 'D'
    opp_defects = sum(1 for h in history if h[1] == 'D')
    if opp_defects * 10 > n * 3:
        return 'D'
    return 'C'
